package com.example.audioinsight.ui;

import android.os.Bundle;
import android.view.View;
import android.widget.*;
import com.example.audioinsight.data.*;
import org.json.*;
import java.util.*;

public class StatsActivity extends UiActivity {
    private LinearLayout charts;private Spinner select;private final ArrayList<RecordInfo> options=new ArrayList<>();private long selected=-1;private boolean settingAdapter;
    @Override public void onCreate(Bundle s){super.onCreate(s);selected=getIntent().getLongExtra("record_id",s==null?-1:s.getLong("record_id",-1));page("声音分析","看见声音里的节奏与参与",getIntent().hasExtra("record_id"),getIntent().hasExtra("record_id")?-1:2);select=new Spinner(this);select.setMinimumHeight(dp(52));select.setBackground(rounded(PANEL,0));body.addView(select,new LinearLayout.LayoutParams(-1,dp(56)));select.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(!settingAdapter&&position<options.size()){selected=options.get(position).id;draw(options.get(position));}}public void onNothingSelected(AdapterView<?> p){}});charts=column();body.addView(charts);}
    @Override protected void onResume(){super.onResume();load();}@Override protected void onRecordsChanged(){load();}
    private void load(){if(charts==null)return;repo.loadRecords("",false,new Callback<List<RecordInfo>>(){public void onSuccess(List<RecordInfo> records){if(isFinishing())return;options.clear();for(RecordInfo r:records)if(r.hasResult())options.add(r);if(options.isEmpty()){charts.removeAllViews();TextView empty=text("还没有可分析的声音\n完成一次识别后，这里会显示真实音高与发言统计。",16,MUTED);empty.setPadding(0,dp(32),0,dp(24));charts.addView(empty);select.setVisibility(View.GONE);return;}select.setVisibility(View.VISIBLE);ArrayList<String> titles=new ArrayList<>();int index=0;for(int i=0;i<options.size();i++){titles.add(options.get(i).title);if(options.get(i).id==selected)index=i;}settingAdapter=true;ArrayAdapter<String> adapter=new ArrayAdapter<>(StatsActivity.this,android.R.layout.simple_spinner_item,titles);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);select.setAdapter(adapter);select.setSelection(index,false);settingAdapter=false;selected=options.get(index).id;draw(options.get(index));}public void onError(String m){error(m);}});}
    private LinearLayout box(String title){LinearLayout c=column();c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(rounded(PANEL,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(16);charts.addView(c,p);TextView t=text(title,18,INK);t.setTypeface(null,android.graphics.Typeface.BOLD);c.addView(t);return c;}
    private void draw(RecordInfo r){charts.removeAllViews();JSONObject result=r.result();JSONObject pitch=result.optJSONObject("pitchStats");LinearLayout pitchBox=box("音高走势");pitchBox.addView(text("原声基频 / Hz",11,CYAN));if(pitch!=null){AudioCharts.Pitch chart=new AudioCharts.Pitch(this,pitch);pitchBox.addView(chart,new LinearLayout.LayoutParams(-1,dp(220)));String avg=number(pitch,"avgHz"),min=number(pitch,"minHz"),max=number(pitch,"maxHz");pitchBox.addView(text("平均 "+avg+" Hz    最低 "+min+" Hz    最高 "+max+" Hz",12,MUTED));pitchBox.addView(text("曲线中的间断表示未检测到有效基频。",12,MUTED));}else{TextView t=text("本次结果未提供音高分析。",14,MUTED);t.setPadding(0,dp(25),0,dp(20));pitchBox.addView(t);}LinearLayout shares=box("发言占比");shares.addView(text("按分句时长估算",11,CYAN));JSONArray segments=result.optJSONArray("segments"),speakers=result.optJSONArray("speakers");Map<String,String> labels=new LinkedHashMap<>();if(speakers!=null)for(int i=0;i<speakers.length();i++){JSONObject sp=speakers.optJSONObject(i);if(sp!=null)labels.put(sp.optString("id"),sp.optString("label",sp.optString("code","发言者")));}LinkedHashMap<String,Double> sums=new LinkedHashMap<>();if(segments!=null)for(int i=0;i<segments.length();i++){JSONObject seg=segments.optJSONObject(i);if(seg==null)continue;double length=Math.max(0,seg.optDouble("end",0)-seg.optDouble("start",0));if(!Double.isFinite(length)||length<=0)continue;String id=seg.optString("speakerId","");if(id.isEmpty()||id.equals("null"))id="unknown";sums.put(id,sums.containsKey(id)?sums.get(id)+length:length);}ArrayList<Double> values=new ArrayList<>(sums.values());AudioCharts.Shares chart=new AudioCharts.Shares(this,values);shares.addView(chart,new LinearLayout.LayoutParams(-1,dp(230)));double total=0;for(double x:values)total+=x;int i=0;for(Map.Entry<String,Double> e:sums.entrySet()){String label=e.getKey().equals("unknown")?"未标注发言者":labels.containsKey(e.getKey())?labels.get(e.getKey()):"发言者 "+(i+1);TextView item=text("●  "+label+"    "+String.format(Locale.CHINA,"%.1f%%",100*e.getValue()/total)+"    "+duration(e.getValue()),13,AudioCharts.COLORS[i%AudioCharts.COLORS.length]);item.setPadding(0,dp(5),0,dp(5));shares.addView(item);i++;}TextView disclaimer=text("占比以所有有效分句的发言时长之和为分母，可能包含重叠；不代表整段音频的占比。未标注内容单独列出。",12,MUTED);disclaimer.setPadding(0,dp(16),0,0);shares.addView(disclaimer);addButton(charts,"查看这条记录",false,v->openRecord(r.id));}
    private String number(JSONObject o,String key){if(o.isNull(key))return "—";double v=o.optDouble(key,Double.NaN);return Double.isFinite(v)?String.format(Locale.CHINA,"%.0f",v):"—";}
    @Override protected void onSaveInstanceState(Bundle b){b.putLong("record_id",selected);super.onSaveInstanceState(b);}
}
